package main

import (
	"errors"
	"regexp"
)

var romanRegexp = regexp.MustCompile(`^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$`)

func RomanToInt(s string) (int, error) {
	if s == "" {
		return 0, errors.New("empty string")
	}
	if !romanRegexp.MatchString(s) {
		return 0, errors.New("invalid Roman numeral")
	}

	vals := map[rune]int{'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
	total := 0
	prev := 0

	for i := len(s) - 1; i >= 0; i-- {
		val := vals[s[i]]
		if val < prev {
			total -= val
		} else {
			total += val
		}
		prev = val
	}

	return total, nil
}
