fn compress(s: &str) -> String {
    let mut result = String::new();
    let mut chars = s.chars();
    match chars.next() {
        None => result,
        Some(first) => {
            let mut current = first;
            let mut count = 1;
            for c in chars {
                if c == current {
                    count += 1;
                } else {
                    result.push(current);
                    if count > 1 {
                        result.push_str(&count.to_string());
                    }
                    current = c;
                    count = 1;
                }
            }
            result.push(current);
            if count > 1 {
                result.push_str(&count.to_string());
            }
            result
        }
    }
}
