fn eval_rpn(tokens: &[&str]) -> Option<i64> {
    let mut stack: Vec<i64> = Vec::new();
    for token in tokens {
        if let Ok(num) = token.parse::<i64>() {
            stack.push(num);
        } else {
            match *token {
                "+" => {
                    let b = stack.pop()?;
                    let a = stack.pop()?;
                    stack.push(a + b);
                }
                "-" => {
                    let b = stack.pop()?;
                    let a = stack.pop()?;
                    stack.push(a - b);
                }
                "*" => {
                    let b = stack.pop()?;
                    let a = stack.pop()?;
                    stack.push(a * b);
                }
                "/" => {
                    let b = stack.pop()?;
                    let a = stack.pop()?;
                    if b == 0 { return None; }
                    stack.push(a / b);
                }
                _ => return None,
            }
        }
    }
    if stack.len() == 1 { Some(stack.pop().unwrap()) } else { None }
}
